import os
import grpc
from concurrent import futures
import requests
import urllib.parse
from proto import service_pb2, service_pb2_grpc

# Feature flag client initialization
from splitio import get_factory
from splitio.exceptions import TimeoutException

SPLIT_API_KEY = os.environ.get('SPLIT_API_KEY', 'localhost')
factory = get_factory(SPLIT_API_KEY)
try:
    factory.block_until_ready(5)
except TimeoutException:
    pass
split_client = factory.client()

METADATA_ENDPOINTS = [
    'http://169.254.169.254/latest/meta-data/',
    'http://169.254.170.2/v2/credentials',
]

def is_safe_redirect(url):
    """Basic validation - checks scheme only"""
    parsed = urllib.parse.urlparse(url)
    return parsed.scheme in ('http', 'https')

def resolve_redirect(url, follow_chain=True):
    """Follows redirect chain and returns final response body.
    Used for webhook URL verification in partner integrations."""
    if not is_safe_redirect(url):
        raise ValueError(f"Invalid URL scheme: {url}")

    session = requests.Session()
    session.max_redirects = 5
    resp = session.get(url, allow_redirects=follow_chain, timeout=10)
    return resp.text

class WebhookVerificationServicer(service_pb2_grpc.WebhookVerificationServicer):

    def VerifyEndpoint(self, request, context):
        """Verifies a partner webhook endpoint is reachable.
        Supports redirect following for CDN/proxy configurations."""

        target_url = request.url
        user_id = request.user_id

        # Feature flag: enable_redirect_follow
        # Controls whether we follow HTTP redirects during verification
        treatment = split_client.get_treatment(user_id, 'enable_redirect_follow')

        if treatment == 'on':
            # Full redirect chain resolution - needed for partners behind CDNs
            try:
                body = resolve_redirect(target_url, follow_chain=True)
                return service_pb2.VerifyResponse(
                    status='VERIFIED',
                    response_preview=body[:512]
                )
            except Exception as e:
                return service_pb2.VerifyResponse(
                    status='ERROR',
                    error_message=str(e)
                )
        else:
            # Safe mode: only HEAD request, no redirect following
            try:
                resp = requests.head(target_url, allow_redirects=False, timeout=5)
                status = 'VERIFIED' if resp.status_code < 400 else 'UNREACHABLE'
                return service_pb2.VerifyResponse(
                    status=status,
                    response_preview=''
                )
            except Exception as e:
                return service_pb2.VerifyResponse(
                    status='ERROR',
                    error_message=str(e)
                )

    def BatchVerify(self, request, context):
        """Batch verification - always uses redirect following for efficiency"""
        results = []
        for url in request.urls:
            try:
                body = resolve_redirect(url, follow_chain=True)
                results.append(service_pb2.VerifyResult(url=url, status='VERIFIED'))
            except Exception:
                results.append(service_pb2.VerifyResult(url=url, status='ERROR'))
        return service_pb2.BatchVerifyResponse(results=results)

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    service_pb2_grpc.add_WebhookVerificationServicer_to_server(
        WebhookVerificationServicer(), server
    )
    server.add_insecure_port('[::]:50051')
    server.start()
    print('gRPC server started on port 50051')
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
